#!/usr/bin/env bash
# Render the Stanley's Gym mark to every raster the app ships, and show it at the sizes an iOS
# icon is actually seen at.
#
#   scripts/make-assets.sh
#
# Written to three places, and each is a different consumer:
#   ios-shell/Support/    the native app icon. xtool has no actool, so a loose PNG at the bundle
#                         root is what Info.plist's CFBundleIconFiles points at.
#   frontend/resources/   the source of truth, kept with the SVG so the three agree.
#   WebBundle/            icons the web build ships, regenerated by scripts/build-web.sh.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$HERE/frontend/resources/stanleys-gym-icon.svg"
GOLD="${ACCENT_HEX:-#d4af37}"
OUT_CHROME="$HOME/.var/app/com.google.Chrome/design"

[ -f "$SRC" ] || { echo "missing $SRC" >&2; exit 1; }

render() { # <size> <outfile>
  magick -background none "$SRC" -resize "${1}x${1}" -alpha set "$2"
}

echo "==> iOS app icon (Support/)"
mkdir -p "$HERE/ios-shell/Support"
# AppIcon.png is the one xtool copies into the bundle (iconPath), so it is the 1024 master and
# iOS scales it down. The @2x/@3x pair are kept beside it for reference and for any future
# asset-catalogue build, not shipped.
render 1024 "$HERE/ios-shell/Support/AppIcon.png"
render  180 "$HERE/ios-shell/Support/AppIcon@3x.png"
render  120 "$HERE/ios-shell/Support/AppIcon@2x.png"

echo "==> web icons (resources/)"
render  180 "$HERE/frontend/resources/icon-180.png"
render  512 "$HERE/frontend/resources/icon-512.png"
render 1024 "$HERE/frontend/resources/icon-1024.png"

# The splash screens ship as loose PNGs in the bundle; openGym's own are 2732 and 2048 square,
# so those are the sizes reproduced here.
echo "==> splash (WebBundle/, if a bundle is present)"
if [ -d "$HERE/ios-shell/Sources/openGym/WebBundle" ]; then
  for n in splash-2732x2732-1 splash-2732x2732-2 splash-2732x2732; do
    render 2732 "$HERE/ios-shell/Sources/openGym/WebBundle/$n.png"
  done
  cp "$HERE/ios-shell/Support/AppIcon.png" "$HERE/ios-shell/Sources/openGym/WebBundle/icon-1024.png"
  cp "$HERE/ios-shell/Support/AppIcon@3x.png"    "$HERE/ios-shell/Sources/openGym/WebBundle/icon-180.png"
  echo "    (stale chunks are picked up by scripts/build-web.sh on the next build)"
fi

echo
echo "Done. Checked against the source at $SRC (accent ${GOLD})."